input.command:
agent-browser eval "(() => {
  const status = document.getElementById('status').innerText;
  const count = document.getElementById('count').innerText;
  const errors = document.getElementById('errors').innerText;
  const eventsList = document.getElementById('events');
  const lis = Array.from(eventsList.querySelectorAll('li'));

  const checks = {
    statusIsDone: status === 'done',
    countIs8: count === '8',
    errorsIs2: errors === '2',
    has8Items: lis.length === 8,
    indicesOrdered: lis.map(li => parseInt(li.getAttribute('data-idx'))).join(',') === '0,1,2,3,4,5,6,7',
    idx0Level: lis[0] && lis[0].getAttribute('data-level') === 'INFO',
    idx0Text: lis[0] && lis[0].innerText.trim() === 'INFO: Server started',
    idx3Level: lis[3] && lis[3].getAttribute('data-level') === 'ERROR',
    idx3Text: lis[3] && lis[3].innerText.trim() === 'ERROR: Failed to connect to cache',
    idx7Level: lis[7] && lis[7].getAttribute('data-level') === 'INFO',
    idx7Text: lis[7] && lis[7].innerText.trim() === 'INFO: Shutdown complete'
  };

  return JSON.stringify(checks, null, 2);
})()"
